#include <Wire.h>
#include <Adafruit_SHT31.h>
#include <math.h>
Adafruit_SHT31 sensor;
bool ready = false;
void setup() {
  Serial.begin(115200); Wire.begin(8, 9);
  ready = sensor.begin(0x44); Serial.println(ready ? "READY" : "SHT31_NOT_FOUND");
